const langNames={'zh':'中文','en':'English','ja':'日本語','ko':'한국어','fr':'Français','de':'Deutsch','es':'Español','pt':'Português','ru':'Русский','ar':'العربية','it':'Italiano','th':'ภาษาไทย'};
const langList=Object.keys(L);
let currentLang=localStorage.getItem('lang')||'zh';

function initLangDropdown(){
  const dd=document.getElementById('langDropdown');
  dd.innerHTML='';
  langList.forEach(l=>{
    const a=document.createElement('a');
    a.href='#';
    a.textContent=langNames[l];
    a.className=l===currentLang?'active':'';
    a.onclick=e=>{e.preventDefault();setLang(l)};
    dd.appendChild(a);
  });
  document.getElementById('currentLang').textContent=langNames[currentLang];
}

function setLang(l){
  currentLang=l;
  localStorage.setItem('lang',l);
  document.querySelectorAll('[data-i18n]').forEach(el=>{
    const k=el.getAttribute('data-i18n');
    if(L[l]&&L[l][k])el.textContent=L[l][k];
  });
  document.querySelectorAll('#langDropdown a').forEach(a=>a.className='');
document.querySelectorAll('.nav-list a').forEach(a=>{
  a.addEventListener('click',function(){
    document.getElementById('navList').classList.remove('open');
  });
});

initLangDropdown();
  document.getElementById('langSwitcher').classList.remove('open');
}

function toggleLang(){
  document.getElementById('langSwitcher').classList.toggle('open');
}

document.addEventListener('click',e=>{
  if(!e.target.closest('.lang-switcher'))document.getElementById('langSwitcher').classList.remove('open');
});

let currentSlide=0;
const slides=document.querySelectorAll('.hero-slide');
const dots=document.querySelectorAll('.hero-dots span');
function goSlide(n){
  if(!slides.length)return;
  slides[currentSlide].classList.remove('active');
  dots[currentSlide].classList.remove('active');
  currentSlide=n;
  slides[currentSlide].classList.add('active');
  dots[currentSlide].classList.add('active');
}
if(slides.length)setInterval(()=>goSlide((currentSlide+1)%slides.length),5000);

const st=document.getElementById('scrollTop');
if(st)window.addEventListener('scroll',()=>{st.classList.toggle('visible',window.scrollY>400)});

const observer=new IntersectionObserver(entries=>{
  entries.forEach(e=>{if(e.isIntersecting)e.target.classList.add('visible')});
},{threshold:0.1});
document.querySelectorAll('.fade-up').forEach(el=>observer.observe(el));

initLangDropdown();
setLang(currentLang);
